// Title: Confirm string overflow handling with CrossStringInPdf setting when converting Excel to PDF using Aspose.Cells for .NET
// Common Searches: how to verify that long text overflows across cells in PDF generated by Aspose.Cells | Aspose.Cells C# check CrossStringInPdf option effect on PDF output | sample code to test string crossing behavior in PDF after saving workbook with Aspose.Cells | does setting column width trigger text overflow in PDF using Aspose.Cells .NET | validate default PdfSaveOptions preserve cell text crossing in exported PDF
// Tags: string overflow validation in PDF conversion | Aspose.Cells PDF save options testing | column width induced text overflow Aspose.Cells | C# Excel to PDF long text handling | verify cell text crossing in exported PDF

using System;
using Aspose.Cells;

// The example creates a workbook, places a long string in cell A1, narrows column A to force the text to cross into adjacent cells, saves the workbook as a PDF with default PdfSaveOptions, and prints the PDF file path, allowing you to confirm that the CrossStringInPdf setting controls string crossing behavior.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook and access the first worksheet
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];

            // Insert a long string that will normally cross the cell boundary
            Cell cell = sheet.Cells["A1"];
            cell.PutValue("This is a very long string that should cross the cell boundary when rendered to PDF.");

            // Set a narrow column width to force the string to cross into adjacent cells
            sheet.Cells.SetColumnWidth(0, 10); // Column A width

            // Prepare PDF save options (default behavior already handles string crossing)
            PdfSaveOptions pdfOptions = new PdfSaveOptions();

            // Save the workbook as PDF
            string pdfPath = "CrossStringDemo.pdf";
            workbook.Save(pdfPath, pdfOptions);

            // Output confirmation
            Console.WriteLine($"PDF saved to '{pdfPath}'.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
